          activeAccountId: USER_ID,
          revision: 1,
          updatedAt: Date.now(),
        },
      })) },
      auth: { signInWithCommonsIdentity: jest.fn(async () => null) },
      users: { me: jest.fn(async (): Promise<User> => ({ id: USER_ID, username: 'cbuser' } as User)), getMany: jest.fn(async () => []) },
      accounts: { list: jest.fn(async () => []) },
      ...overrides,
